'use client';
import {useEffect,useRef,useState,useSyncExternalStore} from 'react';
import Link from 'next/link';
const vocabulary=[{"name": "Monophony", "definition": "One melodic line, performed by one person or by several people together in unison.", "id": "term-1", "explanation": "Follow the tune. More singers do not necessarily mean more independent lines.", "exampleKey": "mono", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "Follow the single tune: no second melody or harmonic backing enters.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Polyphony", "definition": "Two or more simultaneous melodic lines that are independent and comparably important.", "id": "term-2", "explanation": "Follow one line while another continues with a different melody.", "exampleKey": "poly", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "At 2 seconds a second melody enters while the first continues. Follow each line separately.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Drone", "definition": "A sustained pitch, group of pitches, or chord beneath other musical activity.", "id": "term-3", "explanation": "Listen below the changing melody for a sound that remains held.", "exampleKey": "drone", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "The low note remains held while the upper melody changes.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Register", "definition": "The relative pitch range in which a voice or instrument sounds: low, middle, or high.", "id": "term-4", "explanation": "Describe where the sound sits in pitch, rather than how loud it is.", "exampleKey": "register", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Sound and pulse", "listenFor": "At 4 seconds the same melody repeats one octave higher, with the same scheduled gain.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Melisma", "definition": "Several notes sung on one syllable.", "id": "term-5", "explanation": "Track a syllable while the singer moves through multiple pitches.", "exampleKey": "sapientia", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "Follow a single sung vowel as its pitch changes through several notes. The course handout identifies this chant as highly melismatic; do not mistake one long held note for multiple notes.", "cueVerification": "Assigned official recording; source establishes highly melismatic setting, not a newly asserted local timestamp."}, {"name": "Syllabic", "definition": "A text setting with primarily one note per syllable.", "id": "term-6", "explanation": "Check the relationship between text syllables and notes, not the speed.", "exampleKey": "chantar", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "Match successive sung syllables to their notes in A chantar; compare predominantly one-note-per-syllable delivery with any local multi-note ornaments rather than assuming every moment is syllabic.", "cueVerification": "Course handout establishes strophic form; performer upload confirms voice/vielle and verse texts. Exact verse-boundary times not independently assessed."}, {"name": "Strophic", "definition": "The same music returns for successive verses or stanzas.", "id": "term-7", "explanation": "Compare whole verses. A repeated short motif alone does not show strophic form.", "exampleKey": "chantar", "source": "Kendall Terminology Quiz packet; Medieval Music 1–2; Renaissance Music 1.", "category": "Lines and text", "listenFor": "Compare the returning melodic phrase plan across successive sung verse texts over the full performance; allow varied ornaments and accompaniment, and do not infer whole-stanza repetition from one small recurring figure.", "cueVerification": "Course handout establishes strophic form; performer upload confirms voice/vielle and verse texts. Exact verse-boundary times not independently assessed."}, {"name": "Homophony", "definition": "A texture in which a main melody has accompaniment, or voices move together in a chordal rhythm.", "source": "Kendall, Renaissance Music 1, page 1; Classical Music 1, page 1.", "id": "term-8", "explanation": "Ask whether lines move independently or share a coordinated rhythm and foreground melody.", "exampleKey": "homo", "category": "Lines and text", "listenFor": "A foreground tune sounds above chords that change together.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Imitation", "definition": "One voice presents a musical idea that another voice enters with later.", "source": "Kendall, Renaissance Music 1, page 1 (Josquin opening).", "id": "term-9", "explanation": "Follow the opening phrase and listen for it returning in another voice or register.", "exampleKey": "imitation", "category": "Lines and text", "listenFor": "At 2 seconds the lower part enters with the opening idea after the upper part has started.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Dissonance", "definition": "A combination of simultaneous pitches heard as tension or a clash in the musical context.", "source": "Kendall, Renaissance Music 2, pages 1–2 (assigned course handout).", "id": "term-10", "explanation": "Hear how the clash changes and whether it settles into a more stable sound.", "exampleKey": "dissonance", "category": "Sound and pulse", "listenFor": "The middle pair is one semitone apart; compare its roughness with the wider, more stable outer pairs.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Cadence", "definition": "A musical gesture that gives a phrase or section a sense of closure.", "source": "Kendall, Renaissance Music 2, pages 1–2 (assigned course handout).", "id": "term-11", "explanation": "Listen at the end of a phrase for a pause, arrival, or settling of harmony.", "exampleKey": "cadence", "category": "Sound and pulse", "listenFor": "The final two chords move from dominant to tonic in C major. Listen for arrival, not just silence.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Monody", "definition": "A prominent solo vocal melody with a subordinate instrumental accompaniment.", "source": "Kendall, Renaissance Music 2, pages 1–2 (assigned course handout). Caccini is reference-only in the September 22 module.", "id": "term-12", "explanation": "Track which line carries the words and whether the accompaniment supports it.", "exampleKey": "lagrime", "category": "Lines and text", "listenFor": "Follow the solo singer carrying the text and compare the subordinate instrumental support; this includes accompaniment, unlike a single unaccompanied line.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Figured bass", "definition": "A bass line with figures that guide the performer in supplying the harmony.", "source": "Kendall, Renaissance Music 2, pages 1–2 (assigned course handout).", "id": "term-13", "explanation": "This is a notation term; a short recording alone does not prove what was written on the page.", "exampleKey": "bach", "category": "Form and instrumental roles", "listenFor": "Hear the supporting harmony and bass foundation, then consult the score to verify whether figures are written; a recording cannot reveal notation by itself.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Basso continuo", "definition": "A continuing bass foundation with accompanying harmony, commonly realized by players in Baroque music.", "source": "Kendall, Renaissance Music 2, pages 1–2 (assigned course handout).", "id": "term-14", "explanation": "Listen for the bass foundation and harmonic support; identify instruments only when the excerpt supports it.", "exampleKey": "bach", "category": "Form and instrumental roles", "listenFor": "Trace the low foundation and accompanying harmony beneath the solo line; distinguish that supporting function from an exposed keyboard display.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Solo concerto", "definition": "A work that places a solo instrument in interaction with an orchestra.", "source": "Kendall, Classical Music 1 F. 21, page 1 (assigned course handout).", "id": "term-15", "explanation": "Compare moments when the soloist leads, the orchestra leads, and they play together.", "exampleKey": "mozart", "category": "Form and instrumental roles", "listenFor": "Compare piano-leading, orchestra-leading and shared passages across Mozart’s movement; do not require the soloist to play at every moment.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Cadenza", "definition": "A featured solo passage that can sound improvisatory and display the performer’s skill.", "source": "Kendall, Classical Music 1 F. 21, page 1 (assigned course handout).", "id": "term-16", "explanation": "Listen for the orchestra withdrawing while the soloist becomes especially exposed.", "exampleKey": "mozart", "category": "Form and instrumental roles", "listenFor": "Look across the late solo passage for orchestral withdrawal and extended exposed display; verify its location before labeling a particular practice window.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Virtuosity", "definition": "Exceptional performing skill, often displayed through technically demanding passages.", "source": "Kendall, Classical Music 1 F. 21, page 1 (assigned course handout).", "id": "term-17", "explanation": "Listen for demanding speed, range, agility, or control, and describe the particular skill you hear.", "exampleKey": "bach", "category": "Form and instrumental roles", "listenFor": "Identify a concrete demanding feature such as agile runs, rapid changes or wide range; describe the technique rather than merely calling the passage fast.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Galant style", "definition": "An ideal of elegance and balance, with clear phrases, harmonies and often a melody supported by accompaniment.", "source": "Kendall, Classical Music 1 F. 21, page 1 (assigned course handout).", "id": "term-18", "explanation": "Listen for compact question-and-answer phrases and clear changes in mood.", "exampleKey": "mozart", "category": "Form and instrumental roles", "listenFor": "Compare balanced phrase lengths and a question-and-answer relationship, then examine melodic foreground and harmonic clarity; one graceful moment cannot establish an entire style.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Meter", "definition": "The grouping of recurring beats, often in twos (duple) or threes (triple).", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-19", "explanation": "Tap the beat, then find the recurring strong-beat grouping.", "exampleKey": "duple", "category": "Sound and pulse", "listenFor": "Count ONE-two with the stronger click returning every two beats.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Sonata form", "definition": "A large-scale design with exposition, development and recapitulation, often including an introduction or coda.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-20", "explanation": "Compare the presentation, transformation and return of principal material.", "exampleKey": "form", "category": "Form and instrumental roles", "listenFor": "Presentation at 0–10s, transformation at 10–14s, return at 14–22s, and an added close at 22–26s illustrate a simplified thematic plan. A real sonata also has a tonal design; this sketch cannot prove a course movement’s form.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Exposition", "definition": "The section presenting principal thematic material and its tonal contrasts.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-21", "explanation": "Recognize a first subject, transition and contrasting second subject.", "exampleKey": "form", "category": "Form and instrumental roles", "listenFor": "At 0–4s hear A; at 4–6s hear connecting material; at 6–10s hear contrasting B. This schematic presents themes before their transformation and return.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Development", "definition": "A section transforming earlier thematic material, often through fragmentation, recombination and modulation.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-22", "explanation": "Compare short motives with the longer themes heard earlier.", "exampleKey": "form", "category": "Form and instrumental roles", "listenFor": "At 10–14s fragments of A change pitch and shorten. Compare this transformation with the complete statement at 0–4s.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Recapitulation", "definition": "The return of principal thematic material within the home-key framework after development.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-23", "explanation": "Compare the returning themes and their tonal setting with the exposition.", "exampleKey": "form", "category": "Form and instrumental roles", "listenFor": "A returns at 14–18s and B at 18–22s after their earlier presentation and transformation. Recognize the returning material; a real recapitulation also resolves the exposition’s tonal contrast.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Symphony", "definition": "A multi-movement orchestral genre; only Beethoven’s first movement is assigned for this exam.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-24", "explanation": "Listen for orchestral groups and thematic argument without a concerto soloist.", "exampleKey": "beethoven", "category": "Form and instrumental roles", "listenFor": "Follow the argument between orchestral sections in Beethoven without assuming a permanent concerto soloist; the genre needs the work’s identity as well as local sound.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Motif", "definition": "A compact, recognizable musical idea that can be repeated and transformed.", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3; Classical Music 4; October 8 lecture draft (corroboration)", "id": "term-25", "explanation": "Follow a short rhythmic identity across different pitches or instruments.", "exampleKey": "motif", "category": "Form and instrumental roles", "listenFor": "A short four-note idea returns at a different pitch level. Recognize the rhythm despite the changed pitches.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Word painting", "definition": "A musical gesture expresses the meaning of particular words or images in the text.", "source": "Exam guide p. 1; Renaissance Music 2 pp. 1–2; Baroque Music 2 pp. 1–4", "id": "term-26", "explanation": "Use the supplied text and translation to connect meaning with pitch, texture, rhythm or harmony.", "exampleKey": "era", "category": "Lines and text", "listenFor": "Read the relevant text and connect a particular image with a specific musical gesture; for Era compare lower-voice death imagery with the higher-voice merciful-gaze passage after aligning the text.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Through-composed", "definition": "Successive text sections receive changing music rather than repeating the same complete music for every stanza.", "source": "Exam guide p. 1; Renaissance Music 2; Baroque Music 2", "id": "term-27", "explanation": "Compare sections across the work; a local repeated motif can still occur.", "exampleKey": "era", "category": "Lines and text", "listenFor": "Compare the music used for successive text sections across the vocal work; local repeated words or gestures can coexist with changing large-scale settings.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Beat / pulse", "definition": "The recurring reference points you can feel or tap beneath the musical surface.", "explanation": "A beat can continue beneath faster notes or a held melody. Separate that underlying reference from every individual note you hear.", "exampleKey": "pulse", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-28", "category": "Sound and pulse", "listenFor": "Tap the evenly spaced underlying clicks.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Rhythm", "definition": "The pattern of durations and attacks of musical sounds.", "explanation": "Rhythm describes how sounds occupy time. Two lines can have different rhythms while sharing one beat and meter.", "exampleKey": "rhythm", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-29", "category": "Sound and pulse", "listenFor": "The steady clicks continue underneath notes of different lengths. Distinguish the beat from the note pattern.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Tempo", "definition": "The pace of the underlying beat.", "explanation": "Tempo concerns beat speed, rather than note density. Fast subdivisions can occur within a moderate tempo.", "exampleKey": "tempo", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-30", "category": "Sound and pulse", "listenFor": "The second four-beat group is faster than the first, while its grouping remains in fours.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Duple meter", "definition": "Beats regularly group in twos, with a recurring stronger first beat.", "explanation": "Feel the larger strong–weak cycle. Counting all the fastest notes can confuse subdivision with meter.", "exampleKey": "duple", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-31", "category": "Sound and pulse", "listenFor": "Count ONE-two with the stronger click returning every two beats.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Triple meter", "definition": "Beats regularly group in threes.", "explanation": "Feel a recurring strong–weak–weak pattern. Three notes alone do not establish three-beat meter.", "exampleKey": "triple", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-32", "category": "Sound and pulse", "listenFor": "Count ONE-two-three with the stronger click returning every three beats.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Unmetered", "definition": "Music without a regular recurring grouping of beats.", "explanation": "Flexible pacing is not automatically unmetered. Listen over a sustained passage for a repeating beat hierarchy rather than deciding from one pause.", "exampleKey": "unmetered", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-33", "category": "Sound and pulse", "listenFor": "The note onsets are intentionally irregular; no regular strong-beat grouping is supplied.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Unison", "definition": "Several performers share the same melodic line.", "explanation": "More performers can thicken a sound without creating independent melodies. Unison can therefore remain monophonic.", "exampleKey": "unison", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-34", "category": "Lines and text", "listenFor": "Two identical synthetic parts play the same pitches and rhythms; performers do not add independent lines.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Dynamics", "definition": "The relative loudness and changes of loudness in music.", "explanation": "Dynamics are separate from register and tempo. A high pitch can be quiet, and a low pitch can be loud.", "exampleKey": "dynamics", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-35", "category": "Sound and pulse", "listenFor": "The second repetition uses the same pitches but a greater gain. Loudness changes without a register change.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Timbre", "definition": "The characteristic tone quality of a voice or instrument.", "explanation": "Compare attack, sustain and sound colour while controlling for register. High pitch alone cannot identify a flute rather than a violin.", "exampleKey": "timbre", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-36", "category": "Sound and pulse", "listenFor": "The same note is presented with sine, triangle and sawtooth oscillators. Pitch and duration remain constant; the sound quality changes.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Major mode", "definition": "A tonal organization using the major scale and its harmonic relationships.", "explanation": "Mode is a musical structure, not a mood label. Major music can express grief, and an excerpt can visit other tonal areas inside a major work.", "exampleKey": "major", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-37", "category": "Sound and pulse", "listenFor": "Compare C–E–G with C–E-flat–G: the third changes while the tonic remains C.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Minor mode", "definition": "A tonal organization using a minor scale and its harmonic relationships.", "explanation": "Identify tonal relationships rather than treating sadness as a test. Mozart’s D-minor concerto can contain contrasting major passages without changing the whole work’s identity.", "exampleKey": "minor", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-38", "category": "Sound and pulse", "listenFor": "The second chord uses E-flat above C. Compare it with the first chord’s E-natural; sadness is not the test.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Consonance", "definition": "A relatively stable or resolved combination of pitches within its musical context.", "explanation": "Stability depends on style and harmonic function. Compare a relatively settled sonority with tension and the way that tension resolves.", "exampleKey": "consonance", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-39", "category": "Sound and pulse", "listenFor": "Compare the outer open-fifth pairs with the middle semitone pair. These are controlled sound contrasts, not universal emotional rules.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "Theme / subject", "definition": "An identifiable, developed musical idea that can organize a section or movement.", "explanation": "A theme can contain smaller motifs. Track the larger phrase as well as the short cells from which it is made.", "exampleKey": "theme", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-40", "category": "Form and instrumental roles", "listenFor": "Follow the longer opening idea and its contrasting answer. A theme can contain several smaller motifs.", "cueVerification": "Original scheduled sound events; explicit schematic rather than authentic repertoire."}, {"name": "First subject", "definition": "The principal opening thematic material in a sonata exposition.", "explanation": "Identify the opening idea through repeated comparison. Its function involves position and tonal context, not simply that it is loud.", "exampleKey": "form", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-41", "category": "Form and instrumental roles", "listenFor": "Follow A at 0–4s; its repeated rhythm and contour identify a complete opening idea rather than only one note. It returns at 14–18s.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Second subject", "definition": "Contrasting thematic material presented after the first thematic area in a sonata exposition.", "explanation": "Contrast can involve character, texture and tonal area. A second subject need not be performed by a different instrument.", "exampleKey": "form", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-42", "category": "Form and instrumental roles", "listenFor": "At 6–10s B uses a different descending contour, contrasting with A. It returns at 18–22s; “second” means thematic role, not the second individual note.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Transition", "definition": "Material that links thematic areas and often moves away from the initial key.", "explanation": "A transition has a structural role between areas, even when its musical material is memorable. The Beethoven handout identifies descending scale material in its exposition transition.", "exampleKey": "form", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-43", "category": "Form and instrumental roles", "listenFor": "At 4–6s the connecting ascending figure moves from A toward B. Hear its bridging role; in a real sonata it often also prepares a change of key.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Coda", "definition": "An ending section extending or concluding material after the principal formal return.", "explanation": "A final loud chord is not itself a coda. Locate a sustained concluding section through its relationship to the preceding form.", "exampleKey": "form", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-44", "category": "Form and instrumental roles", "listenFor": "At 22–26s a short added closing idea follows the returned themes. Its position after the principal return makes it a coda in this constructed sketch.", "cueVerification": "Original schematic A/transition/B/transformation/A/B/coda score, not a complete sonata movement."}, {"name": "Concerto grosso", "definition": "A concerto featuring a small solo group in relation to a larger ensemble.", "explanation": "Track changes of prominence between groups rather than merely counting performers. Bach’s fifth Brandenburg uses flute, violin and harpsichord as its concertino.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-45", "category": "Form and instrumental roles", "listenFor": "Follow changes of prominence between Bach’s three-instrument solo group and the accompanying ensemble; total player count does not establish the design.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Concertino", "definition": "The small group of featured soloists in a concerto grosso.", "explanation": "In Brandenburg no. 5 this group is flute, violin and harpsichord. Its members can lead separately or together.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-46", "category": "Form and instrumental roles", "listenFor": "Track flute, violin and harpsichord as Bach’s identified solo group, individually and together; membership stays the same when a member temporarily supports another.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Ripieno", "definition": "The larger accompanying ensemble in a concerto grosso.", "explanation": "Supporting does not mean inaudible or musically unimportant. Listen for changes between fuller ensemble statements and solo-group prominence.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-47", "category": "Form and instrumental roles", "listenFor": "Compare the fuller supporting string group with concertino-led passages; the harpsichord can also participate in the accompanying continuo role.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Madrigal", "definition": "A secular vocal genre strongly concerned with the expressive musical setting of a text.", "explanation": "Monteverdi’s assigned example uses mixed voices and changing textures. Polyphony alone does not distinguish a madrigal from sacred vocal genres.", "exampleKey": "era", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-48", "category": "Lines and text", "listenFor": "Connect Monteverdi’s mixed-voice setting and changing textures with its secular text; polyphony alone cannot distinguish madrigal from motet.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Motet", "definition": "A sacred vocal genre, commonly with polyphonic writing.", "explanation": "This is comparison vocabulary in the guide, not a sixth assigned exam work. The sacred function of the text helps distinguish it from a secular madrigal; texture alone is insufficient.", "exampleKey": "motet", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-49", "category": "Lines and text", "listenFor": "Compare sacred textual function with the secular madrigal rather than classifying by texture alone; use a documented motet, not O Sapientia chant, for a genre example.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Cantata", "definition": "A vocal composition, often combining contrasting kinds of delivery and instrumental support.", "explanation": "Strozzi’s assigned cantata is secular and features soprano with continuo. The genre does not mean an unaccompanied choir.", "exampleKey": "lagrime", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-50", "category": "Lines and text", "listenFor": "Follow Strozzi’s soprano and instrumental accompaniment across contrasting text sections; solo voice with support is the performing configuration here, not a definition of every cantata.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Lament", "definition": "Music expressing grief or mourning.", "explanation": "Strozzi’s text and musical expression give the label substance. A minor key alone does not establish a lament.", "exampleKey": "lagrime", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-51", "category": "Lines and text", "listenFor": "Read the grief and tears imagery, then compare how vocal pacing, dissonance and text setting contribute to expression; a minor sound alone does not establish lament.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Secular", "definition": "Music whose text or function is not primarily sacred or liturgical.", "explanation": "The madrigal and Strozzi cantata in the guide are secular. Secular music can still be serious, emotionally intense or polyphonic.", "exampleKey": "era", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-52", "category": "Lines and text", "listenFor": "Use the love or grief subject matter of the supplied vocal text to establish non-liturgical context; no single instrument or texture proves secular function.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Sacred", "definition": "Music connected with religious text or function.", "explanation": "A sacred text or setting is contextual evidence, not a sound colour. An unaccompanied choir is not automatically sacred.", "exampleKey": "motet", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-53", "category": "Lines and text", "listenFor": "Read O Sapientia’s religious text and documented chant context; unaccompanied voices alone do not establish sacred purpose.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Soprano", "definition": "A high vocal register or voice part.", "explanation": "Listen for relative pitch range rather than loudness. Strozzi’s assigned work places a soprano in the foreground with instrumental support.", "exampleKey": "lagrime", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-54", "category": "Lines and text", "listenFor": "Follow Strozzi’s identified solo vocal part and its relative range against the accompaniment; loudness does not define the soprano range.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Alto", "definition": "A voice part below the soprano range in a standard mixed vocal grouping.", "explanation": "Compare relative ranges within the ensemble. A quieter line is not necessarily an alto part.", "exampleKey": "era", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-55", "category": "Lines and text", "listenFor": "Within Monteverdi’s documented mixed voices, compare a middle-lower vocal line with upper and lower parts; confirm part identity from score or credits when lines overlap.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Tenor", "definition": "A voice part above bass and below the higher parts in a standard mixed vocal grouping.", "explanation": "Register describes its place in pitch space. The sound of several voices together can make individual parts harder to follow.", "exampleKey": "era", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-56", "category": "Lines and text", "listenFor": "Compare a middle male vocal range with the lower bass and upper voices; do not identify tenor solely from a single pitch in a shared range.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Bass", "definition": "The low vocal part or the low musical foundation of an ensemble.", "explanation": "Distinguish the vocal range from the structural bass line. A bass line can be played by an instrument rather than sung.", "exampleKey": "era", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-57", "category": "Lines and text", "listenFor": "Trace the lowest sung part within mixed voices, then distinguish that voice type from the structural bass function also carried by instruments.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Strings", "definition": "The instrumental family including violin, viola, cello and double bass.", "explanation": "Bowed attacks and sustained lines offer clues, but playing technique can change timbre. Bach’s ripieno includes several string registers.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-58", "category": "Form and instrumental roles", "listenFor": "Compare bowed attacks, sustained tone and occasional plucked articulation across Bach’s string registers; verify identities through the ensemble credits.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Woodwinds", "definition": "The family including flute, oboe, clarinet and bassoon.", "explanation": "Compare distinctive tone qualities rather than classifying every high sound as flute. Bach’s flute is a concertino instrument; the Mozart guide highlights a larger woodwind section.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-59", "category": "Form and instrumental roles", "listenFor": "Compare wind tone and articulation in Bach’s flute and the Classical orchestras; confirm identities instead of labeling every high tone flute.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Brass", "definition": "The family including horns, trumpets, trombones and tuba.", "explanation": "Not every member appears in every orchestra or movement. The course handout explicitly excludes brass from Bach’s Brandenburg no. 5 ensemble.", "exampleKey": "beethoven", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-60", "category": "Form and instrumental roles", "listenFor": "Use a documented orchestral passage to compare brass attacks and sustained tone with winds and strings; Bach’s specified ensemble contains no brass.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Percussion", "definition": "Instruments whose sound is produced by striking or related actions, including orchestral drums.", "explanation": "Percussion can reinforce an orchestral accent without creating a melody. Do not assume it is present in Bach’s ensemble, where the handout says it is absent.", "exampleKey": "beethoven", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-61", "category": "Form and instrumental roles", "listenFor": "Check orchestral credits and locate struck rhythmic accents if present; Bach’s harpsichord jackrail sound is not evidence of a scored percussion part.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Keyboard", "definition": "Instruments played through keys, including piano and harpsichord.", "explanation": "Keyboard is a family or interface, not one timbre. Piano strings are struck, whereas harpsichord strings are plucked.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-62", "category": "Form and instrumental roles", "listenFor": "Compare Mozart’s piano and Bach’s harpsichord for attack, decay and changing roles; the shared keyboard interface does not imply identical sound production.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Harpsichord", "definition": "A keyboard instrument whose strings are plucked.", "explanation": "Its role can change from continuo support to an exposed virtuoso solo. Identifying the instrument does not by itself determine which role it has at that moment.", "exampleKey": "bach", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-63", "category": "Form and instrumental roles", "listenFor": "Trace the plucked keyboard sound through supporting chords and exposed solo display in Bach; its instrument identity is distinct from its changing musical role.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"name": "Piano", "definition": "A keyboard instrument whose strings are struck by hammers.", "explanation": "In Mozart’s assigned concerto it is the principal solo instrument. The orchestra can lead an excerpt while the work remains a piano concerto.", "exampleKey": "mozart", "source": "Kendall Listening Exam Study Guide pp. 1–2; Baroque Music 3 pp. 1–2; Classical Music 1 and 4.", "id": "term-64", "category": "Form and instrumental roles", "listenFor": "Follow the principal solo keyboard line and compare its attack and orchestral interactions in Mozart; an orchestra-only passage remains part of the piano concerto.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-65", "name": "Flute", "definition": "A woodwind instrument sounded by blowing across an opening.", "explanation": "Bach’s concertino includes flute, violin and harpsichord. Follow the upper solo line, but confirm its identity against the performer credits rather than identifying it from pitch alone.", "exampleKey": "bach", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Follow Bach’s credited traverso line and compare its wind tone with the bowed violin in a similar range; modern-flute timbre should not be assumed for this period-instrument recording.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-66", "name": "Violin", "definition": "The highest-register standard bowed string instrument.", "explanation": "A violin can carry an independent melody or join the orchestral strings. In Brandenburg no. 5 it is also a member of the concertino.", "exampleKey": "bach", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Follow Bach’s credited solo violin against flute and keyboard, then compare it with ensemble string writing; solo prominence and instrument family are separate claims.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-67", "name": "Viola", "definition": "A bowed string instrument with a range lower than the violin.", "explanation": "Its middle-register line can support harmony or carry an independent melody. Register and musical role are useful observations even when an individual instrument is difficult to isolate.", "exampleKey": "bach", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Use score or credits to locate Bach’s middle string part and follow its harmonic or melodic role; middle register alone cannot reliably isolate viola in the mix.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-68", "name": "Cello", "definition": "A bowed string instrument that commonly plays in a low register.", "explanation": "It can supply a bass foundation or a melodic line. A low pitch alone does not distinguish a cello from every other bass instrument.", "exampleKey": "bach", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Follow the credited low bowed-string line and its bass-foundation role; compare with other bass instruments before naming a specific isolated sound.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-69", "name": "Double bass / violone", "definition": "Low-register bowed strings used for a bass foundation; historical instrument names and construction vary.", "explanation": "Use the recording credits to distinguish the actual instrument. In the concerto, listen for the bass line supporting the ensemble.", "exampleKey": "bach", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Use recording credits to establish whether the lower instrument is violone or double bass, then trace its support of the ensemble’s bass foundation.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-70", "name": "Oboe", "definition": "A double-reed woodwind instrument.", "explanation": "Beethoven’s handout identifies an exposed oboe solo during the recapitulation of the first movement. Its exact time in this alternative performance has not been aligned to the handout.", "exampleKey": "beethoven", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Compare Beethoven’s returning first theme with its exposition for the source-described exposed oboe interruption; align the alternative performance before assigning a time.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}, {"id": "term-71", "name": "Bassoon", "definition": "A low-register double-reed woodwind instrument.", "explanation": "Beethoven’s handout identifies a bassoon solo in the recapitulation transition. Do not transfer the handout’s timestamp to another performance.", "exampleKey": "beethoven", "source": "Listening Exam Study Guide pp. 1–2; Baroque Music 3 / Classical Music 4", "category": "Form and instrumental roles", "listenFor": "Compare Beethoven’s recapitulation transition with earlier transition material for the source-described bassoon role; the Haitink clock time is not transferable to Zander.", "cueVerification": "Whole-work source-grounded observation task; exact audible cue location not independently assessed."}];
